// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> decrypt(vector<int>& code, int k) {
        vector<int> result(size(code));
        if (k == 0) {
            return result;
        }
        int left = 1, right = k;
        if (k < 0) {
            k = -k;
            left = size(code) - k, right = size(code) - 1;
        }
        int total = accumulate(begin(code) + left, begin(code) + right + 1, 0);
        for (int i = 0; i < size(code); ++i) {
            result[i] = total;
            total -= code[left++ % size(code)];
            total += code[++right % size(code)];
        }
        return result;
    }
};

kamyu-c-degree-of-an-array-0eaqmds:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int findShortestSubArray(vector<int>& nums) {
        unordered_map<int, int> left, right;
        unordered_map<int, int> counts;
        for (int i = 0; i < nums.size(); ++i) {
            if (left.count(nums[i]) == 0) {
                left[nums[i]] = i;
            }
            right[nums[i]] = i;
            ++counts[nums[i]];
        }
        auto degree = max_element(counts.begin(), counts.end(),
                                  [](const pair<int, int>& a,
                                     const pair<int, int>& b) {
                                      return a.second < b.second;
                                  })->second;
        auto result = numeric_limits<int>::max();
        for (const auto& kvp : counts) {
            if (kvp.second == degree) {
                result = min(result, right[kvp.first] - left[kvp.first] + 1);
            }
        }
        return result;
    }
};

