// design
class Bitset {
public:
    Bitset(int size)
      : lookup_(size) {

    }

    void fix(int idx) {
        if (lookup_[idx] == flip_) {
            lookup_[idx] = !lookup_[idx];
            ++cnt_;
        }
    }

    void unfix(int idx) {
         if (lookup_[idx] != flip_) {
            lookup_[idx] = !lookup_[idx];
            --cnt_;
        }
    }

    void flip() {
        flip_ = !flip_;
        cnt_ = size(lookup_) - cnt_;
