class FrontMiddleBackQueue {
public:
    FrontMiddleBackQueue() {

    }

    void pushFront(int val) {
        left_.emplace_front(val);
        balance();
    }

    void pushMiddle(int val) {
        if (size(left_) > size(right_)) {
            right_.emplace_front(left_.back());
            left_.pop_back();
        }
        left_.emplace_back(val);
    }

    void pushBack(int val) {
        right_.emplace_back(val);
        balance();
    }

    int popFront() {
        int result = -1;
        if (!empty(left_)) {
            result = left_.front();
            left_.pop_front();
        }
        balance();
        return result;
    }

    int popMiddle() {
        int result = -1;
        if (!empty(left_)) {
            result = left_.back();
            left_.pop_back();
        }
        balance();
        return result;
    }

    int popBack() {
        int result = -1;
        if (!empty(right_)) {
            result = right_.back();
            right_.pop_back();
        } else if (!empty(left_)) {
            result = left_.back();
            left_.pop_back();
        }
        balance();
        return result;
    }

private:
    void balance() {
        if (size(left_) > size(right_) + 1) {
            right_.emplace_front(left_.back());
            left_.pop_back();
        } else if (size(left_) < size(right_) ) {
            left_.emplace_back(right_.front());
            right_.pop_front();
        }
    }

    // using list<int> is also fine but slower
    deque<int> left_;
    deque<int> right_;
};

kamyu-c-design-graph-with-shortest-path-:
// Time:  ctor:         O(|V| + |E|)
//        addEdge:      O(1)
//        shortestPath: O((|E| + |V|) * log|V|) = O(|E| * log|V|)
// Space: O(|E| + |V|) = O(|E|)

// dijkstra's algorithm
class Graph {
public:
    Graph(int n, vector<vector<int>>& edges) : adj_(n) {
        for (const auto& edge : edges) {
            addEdge(edge);
        } 
    }

    void addEdge(vector<int> edge) {
        adj_[edge[0]].emplace_back(edge[1], edge[2]);
    }

    int shortestPath(int node1, int node2) {
        const auto& dijkstra = [](const auto& adj, int start, int target) {
            static const int INF = numeric_limits<int>::max();

            vector<int> best(size(adj), INF);
            best[start] = 0;
            priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> min_heap;
            min_heap.emplace(0, start);
            while (!empty(min_heap)) {
                const auto [curr, u] = min_heap.top(); min_heap.pop();
                if (curr > best[u]) {
                    continue;
                }
                if (u == target) {
                    break;
                }
                for (const auto& [v, w] : adj[u]) {
                    if (!(w < best[v] - curr)) {
                        continue;
                    }
                    best[v] = curr + w;
                    min_heap.emplace(curr + w, v);
                }
            }
            return best[target] != INF ? best[target] : -1;
        };

        return dijkstra(adj_, node1, node2);
    }

private:
    vector<vector<pair<int, int>>> adj_;
};

