// bst
class TaskManager {
public:
    TaskManager(vector<vector<int>>& tasks) {
        for (const auto& t : tasks) {
            add(t[0], t[1], t[2]);
        }
    }

    void add(int userId, int taskId, int priority) {
        bst_.emplace(priority, taskId, userId);
        lookup_[taskId] = pair(userId, priority);
    }

    void edit(int taskId, int newPriority) {
        const auto [userId, _] = lookup_[taskId];
        rmv(taskId);
        add(userId, taskId, newPriority);
    }

    void rmv(int taskId) {
        const auto [userId, priority] = lookup_[taskId];
        lookup_.erase(taskId);
        bst_.erase(tuple(priority, taskId, userId));
    }

    int execTop() {
        if (empty(bst_)) {
            return -1;
        }
        const auto [_, taskId, userId] = *rbegin(bst_);
        rmv(taskId);
        return userId;
    }

private:
    unordered_map<int, pair<int, int>> lookup_;
    set<tuple<int, int, int>> bst_;
};

kamyu-c-design-tic-tac-toe-0i9mwel:
// Time:  O(1), per move.
// Space: O(n^2)

class TicTacToe {
public:
    /** Initialize your data structure here. */
    TicTacToe(int n) : rows_(n, {0, 0}), cols_(n, {0, 0}),
                       diagonal_(2, 0), anti_diagonal_(2, 0) {
    }

    /** Player {player} makes a move at ({row}, {col}).
        @param row The row of the board.
        @param col The column of the board.
        @param player The player, can be either 1 or 2.
        @return The current winning condition, can be either:
                0: No one wins.
                1: Player 1 wins.
                2: Player 2 wins. */
    int move(int row, int col, int player) {
        const auto i = player - 1;
        ++rows_[row][i], ++cols_[col][i];
        if (row == col) {
            ++diagonal_[i];
        }
        if (col == rows_.size() - row - 1) {
            ++anti_diagonal_[i];
        }
        if (rows_[row][i] == rows_.size() ||
            cols_[col][i] == cols_.size() ||
            diagonal_[i] == rows_.size() ||
            anti_diagonal_[i] == cols_.size()) {
            return player;
        }
        return 0;
    }

private:
    vector<vector<int>> rows_, cols_;
    vector<int> diagonal_, anti_diagonal_;
};

