// Space: O(1)

class Solution {
public:
    int distanceBetweenBusStops(vector<int>& distance, int start, int destination) {
        if (start > destination) {
            swap(start, destination);
        }
        const auto& s_to_d = accumulate(distance.cbegin() + start,
                                        distance.cbegin() + destination, 0);
        const auto& d_to_s = accumulate(distance.cbegin(),
                                        distance.cbegin() + start, 0) +
                             accumulate(distance.cbegin() + destination,
                                        distance.cend(), 0);
        return min(s_to_d, d_to_s);
    }
};

kamyu-c-distance-to-a-cycle-in-undirecte:
// Time:  O(|V| + |E|)
// Space: O(|V| + |E|)

// graph, dfs, bfs
class Solution {
public:
    vector<int> distanceToCycle(int n, vector<vector<int>>& edges) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        return bfs(adj, iter_dfs(adj));
    }

private:
    vector<int> cycle(const vector<int>& parent, int v, int u) {
        vector<int> result = {parent[v], v};
        for (; u != parent[v]; u = parent[u]) {
            result.emplace_back(u);
        }
        return result;
    }

    vector<int> iter_dfs(const vector<vector<int>>& adj) {
        vector<int> stk = {0};
        vector<int> parent(size(adj), -2);
        parent[0] = -1;
        while (!empty(stk)) {
            const int u = stk.back(); stk.pop_back();
            for (const auto& v : adj[u]) {
                if (parent[v] != -2) {
                    if (v == parent[u]) {
                        continue;
                    }
                    return cycle(parent, v, u);
                }
                parent[v] = u;
                stk.emplace_back(v);
            }
        }
        return {};
    }

    vector<int> bfs(const vector<vector<int>>& adj, vector<int> q) {
        vector<int> result(size(adj), -1);
        for (const auto& x : q) {
            result[x] = 0;
        }
        for (int d = 1; !empty(q); ++d) {
            vector<int> new_q;
            for (const auto& u : q) {
                for (const auto& v : adj[u]) {
                    if (result[v] != -1) {
                        continue;
                    }
                    result[v] = d;
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return result;
    }
};

kamyu-c-distant-barcodes-1ap589z:
// Time:  O(n), k is the number of distinct barcode
// Space: O(k)

class Solution {
public:
    vector<int> rearrangeBarcodes(vector<int>& barcodes) {
        static const int k = 2;

        unordered_map<int, int> cnts;
        for (const auto& c : barcodes) {
            ++cnts[c];
        }
        const int bucket_cnt = max_element(cbegin(cnts), cend(cnts), [](const auto& a, const auto& b) {
            return a.second < b.second;
        })->second;
        vector<int> partial_sorted_cnts;
        for (const auto& [c, v] : cnts) {
            if (v == bucket_cnt) {
                partial_sorted_cnts.emplace_back(c);
            }
        }
        for (const auto& [c, v] : cnts) {
            if (v != bucket_cnt) {
                partial_sorted_cnts.emplace_back(c);
            }
        }
        vector<int> result(size(barcodes));
        int i = (size(barcodes) - 1) % k;
        for (const auto& c : partial_sorted_cnts) {
            for (int _ = 0; _ < cnts[c]; ++_) {
                result[i] = c;
                i += k;
                if (i >= size(result)) {
                    i = (i - 1) % k;
                }
            }
        }
        return result;
    }
};

