        vector<int> result;
        unordered_map<int, int> count;
        for (int i = 0; i < size(nums); ++i) {
            ++count[nums[i]];
            if (i >= k) {
                if (--count[nums[i - k]] == 0) {
                    count.erase(nums[i - k]);
