        if (money < children * 1) {
            return -1;
        }
        money -= children * 1;
        const int q = money / 7, r = money % 7;
        if (q > children) {
            return children - 1;
        }
        if (q == children) {
            return q - static_cast<int>(r != 0);
        }
        if (q == children - 1) {
            return q - static_cast<int>(r == 3);
        }
        return q;
    }
};

