// Time:  O(k * n^2)
// Space: O(n)
class Solution2 {
public:
    int twoEggDrop(int n) {
        static const int K = 2;
        vector<vector<int>> dp(2, vector<int>(n + 1, numeric_limits<int>::max()));
        for (int j = 0; j <= n; ++j) {
            dp[1][j] = j;
        }
        for (int i = 2; i <= K; ++i) {
            dp[i % 2][0] = 0;
            for (int j = 1; j <= n; ++j) {
                for (int k = 1; k <= j; ++k) {
                    dp[i % 2][j] = min(dp[i % 2][j], 1 + max(dp[(i - 1) % 2][k - 1], dp[i % 2][j - k]));
                }
            }
        }
        return dp[K % 2][n];
    }
};

