        int result = 0;
        for (int k = 0; k < 2; ++k) {
            for (int i = k; i < size(initial); ++i) {
                int curr = 0;
                for (int j = 0; j < min(size(initial) - i, size(target)); ++j) {
                    curr = initial[i + j] == target[j] ? curr + 1 : 0;
                    result = max(result, curr);
                }
            }
            swap(initial, target);
        }
        return size(initial) + size(target) - 2 * result;
    }
};

