kamyu-c-excel-sheet-column-title-1qi40bn:
// Time:  O(logn)
// Space: O(1)

// Iterative solution.
class Solution {
public:
    string convertToTitle(int n) {
        string result;
        int dvd{n};

        while (dvd) {
            result.push_back((dvd - 1) % 26 + 'A');
            dvd = (dvd - 1) / 26;
        }
        reverse(result.begin(), result.end());

        return result;
    }
};

// Time:  O((logn)^2)
// Space: O(logn)
// Recursive solution.
class Solution2 {
public:
    string convertToTitle(int n) {
        if (n == 0) {
            return "";
        }
        return convertToTitle((n - 1) / 26) + static_cast<char>((n - 1) % 26 + 'A');
    }
};

kamyu-c-exclusive-time-of-functions-0ce1:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    vector<int> exclusiveTime(int n, vector<string>& logs) {
        vector<int> result(n);
        stack<int> stk;
        int prev = 0;
        for (const auto& log : logs) {
            vector<string> tokens = split(log, ':');
            if (tokens[1] == "start") {
                if (!stk.empty()) {
                    result[stk.top()] += stoi(tokens[2]) - prev;
                }
                stk.emplace(stoi(tokens[0]));
                prev = stoi(tokens[2]);
            } else {
                result[stk.top()] += stoi(tokens[2]) - prev + 1;
                stk.pop();
                prev = stoi(tokens[2]) + 1;
            }
        }
        return result;
    }

private:
    vector<string> split(const string& s, const char delim) {
        vector<string> tokens;
        stringstream ss(s);
        string token;
        while (getline(ss, token, delim)) {
            tokens.emplace_back(token);
        }
        return tokens;
    }
};

kamyu-c-execution-of-all-suffix-instruct:
// Time:  O(m)
// Space: O(m)

class Solution {
public:
    vector<int> executeInstructions(int n, vector<int>& startPos, string s) {
        static const unordered_map<char, pair<int, int>> directions = {
            {'U', {-1, 0}}, {'R', {0, 1}}, {'D', {1, 0}}, {'L', {0, -1}}
        };

        int x0 = startPos[0], y0 = startPos[1];
        int x = 0, y = 0;
        vector<int> result(size(s));
        iota(rbegin(result), rend(result), 1);
        unordered_map<int, vector<int>> lookup_x, lookup_y;
        lookup_x[x0 - x].emplace_back(0);
        lookup_y[y0 - y].emplace_back(0);
        for (int i = 0; i < size(s); ++i) {
            const auto& [dx, dy] = directions.at(s[i]);
            x += dx, y += dy;
            for (const auto& k : {n - x, -x - 1}) {
                if (!lookup_x.count(k)) {
                    continue;
                }
                for (const auto& j : lookup_x[k]) {
                    result[j] = min(result[j], i - j);
                }
                lookup_x.erase(k);
            }
            for (const auto& k : {n - y, -y - 1}) {
                if (!lookup_y.count(k)) {
                    continue;
                }
                for (const auto& j : lookup_y[k]) {
                    result[j] = min(result[j], i - j);
                }
                lookup_y.erase(k);
            }
            lookup_x[x0 - x].emplace_back(i + 1);
            lookup_y[y0 - y].emplace_back(i + 1);
        }
        return result;
    }
};

