        unordered_map<char, unordered_set<char>> lookup;
        for (int i = 0; i + 1 < size(s); ++i) {
            lookup[s[i]].emplace(s[i + 1]);
        }
        for (int i = 0; i + 1 < size(s); ++i) {
            if (lookup[s[i + 1]].count(s[i])) {
