kamyu-c-expression-add-operators-1foktly:
// Time:  O(4^n)
// Space: O(n)

class Solution {
public:
    vector<string> addOperators(string num, int target) {
        vector<string> result;
        vector<string> expr;
        int val = 0;
        string val_str;
        for (int i = 0; i < num.length(); ++i) {
            val = val * 10 + num[i] - '0';
            val_str.push_back(num[i]);
            // Avoid overflow and "00...".
            if (to_string(val) != val_str) {
                break;
            }
            expr.emplace_back(val_str);
            addOperatorsDFS(num, target, i + 1, 0, val, &expr, &result);
            expr.pop_back();
        }
        return result;
    }

    void addOperatorsDFS(const string& num, const int& target, const int& pos,
                         const int& operand1, const int& operand2,
                         vector<string> *expr, vector<string> *result) {
        if (pos == num.length() && operand1 + operand2 == target) {
            result->emplace_back(join(*expr));
        } else {
            int val = 0;
            string val_str;
            for (int i = pos; i < num.length(); ++i) {
                val = val * 10 + num[i] - '0';
                val_str.push_back(num[i]);
                // Avoid overflow and "00...".
                if (to_string(val) != val_str) {
                    break;
                }

                // Case '+':
                expr->emplace_back("+" + val_str);
                addOperatorsDFS(num, target, i + 1, operand1 + operand2, val, expr, result);
                expr->pop_back();

                // Case '-':
                expr->emplace_back("-" + val_str);
                addOperatorsDFS(num, target, i + 1, operand1 + operand2, -val, expr, result);
                expr->pop_back();

                // Case '*':
                expr->emplace_back("*" + val_str);
                addOperatorsDFS(num, target, i + 1, operand1, operand2 * val, expr, result);
                expr->pop_back();
            }
        }
    }

    string join(const vector<string>& expr) {
        ostringstream stream;
        copy(expr.cbegin(), expr.cend(), ostream_iterator<string>(stream));
        return stream.str();
    }
};

kamyu-c-expressive-words-0j1dodk:
// Time:  O(n + s), n is the sum of all word lengths, s is the length of S
// Space: O(l + s)

class Solution {
public:
    int expressiveWords(string S, vector<string>& words) {
        int result = 0;
        const auto& R = RLE(S);
        for (const auto& word : words) {
            const auto& R2 = RLE(word);
            if (R.key != R2.key) {
                continue;
            }
            int i;
            for (i = 0; i < R.counts.size(); ++i) {
               const auto& c1 = R.counts[i];
               const auto& c2 = R2.counts[i];
               if (c1 < max(c2, 3) && c1 != c2) {
                   break;
               }
            }
            if (i == R.counts.size()) {
                ++result;
            }
        }
        return result;
    }

private:
    struct RLE {
        string key;
        vector<int> counts;
        RLE(const string& s) {
            int prev = -1;
            for (int i = 0; i < s.length(); ++i) {
                if (i == s.length() - 1 || s[i] != s[i + 1]) {
                    key.push_back(s[i]);
                    counts.emplace_back(i - prev);
                    prev = i;
                }
            }
        }
    };
};

kamyu-c-extra-characters-in-a-string-176:
// Time:  O((n + m) * l), l is max(len(w) for w in dictionary)
// Space: O(n + t)

// trie, dp
class Solution {
public:
    int minExtraChar(string s, vector<string>& dictionary) {
        Trie trie;
        for (const auto& w : dictionary) {
            trie.insert(w);
        }
        vector<int> dp(size(s) + 1, numeric_limits<int>::max());
        dp[0] = 0;
        for (int i = 0; i < size(s); ++i) {
            dp[i + 1] = min(dp[i + 1], dp[i] + 1);
            for (int j = i, curr = 0; j < size(s); ++j) {
                curr = trie.child(curr, s[j]);
                if (!curr) {
                    break;
                }
                if (trie.is_string(curr)) {
                    dp[j + 1] = min(dp[j + 1], dp[i]);
                }
            }
        }
        return dp.back();
    }

private:
class Trie {
    public:
        Trie() {
            create_node(); 
        }

        void insert(const string& s) {
            int curr = 0;
            for (const auto& c : s) {
                if (!nodes_[curr][c - 'a']) {
                    nodes_[curr][c - 'a'] = create_node();
                }
                curr = nodes_[curr][c - 'a'];
            }
            ++nodes_[curr].back();
        }

        int child(int curr, char c) const {
            return nodes_[curr][c - 'a'];
        }

        bool is_string(int curr) const {
            return nodes_[curr].back();
        }

    private:
        int create_node() {
            nodes_.emplace_back(26 + 1);
            return size(nodes_) - 1;
        }

        using TrieNode = vector<int>;
        vector<TrieNode> nodes_;
    };
};

