        }
        return dfs(adj, start, end);
    }

private:
    int dfs(const unordered_map<int, vector<int>>& adj,
               const int start,
               const int target) {
        vector<int> stk = {start};
        unordered_set<int> lookup;
        while (!empty(stk)) {
            auto pos = stk.back(); stk.pop_back();
            if (pos == target) {
                return true;
            }
            if (!adj.count(pos)) {
                continue;
            }
            for (const auto& nei : adj.at(pos)) {
                if (lookup.count(nei)) {
                    continue;
                }
                lookup.emplace(nei);
                stk.emplace_back(nei);
            }
