kamyu-c-find-k-pairs-with-smallest-sums-:
// Time:  O(k * log(min(n, m, k))), where n is the size of num1, and m is the size of num2.
// Space: O(min(n, m, k))

class Solution {
public:
    vector<pair<int, int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        vector<pair<int, int>> pairs;
        if (nums1.size() > nums2.size()) {
            vector<pair<int, int>> tmp = kSmallestPairs(nums2, nums1, k);
            for (const auto& pair : tmp) {
                pairs.emplace_back(pair.second, pair.first);
            }
            return pairs;
        }

        using P = pair<int, pair<int, int>>;
        priority_queue<P, vector<P>, greater<P>> q;
        auto push = [&nums1, &nums2, &q](int i, int j) {
            if (i < nums1.size() && j < nums2.size()) {
                q.emplace(nums1[i] + nums2[j], make_pair(i, j));
            }
        };

        push(0, 0);
        while (!q.empty() && pairs.size() < k) {
            auto tmp = q.top(); q.pop();
            int i, j;
            tie(i, j) = tmp.second;
            pairs.emplace_back(nums1[i], nums2[j]);
            push(i, j + 1);
            if (j == 0) {
                push(i + 1, 0);  // at most queue min(m, n) space.
            }
        }
        return pairs; 
    }
};

kamyu-c-find-k-th-smallest-pair-distance:
// Time:  O(nlogn + nlogw), n = len(nums), w = max(nums) - min(nums)
// Space: O(1)

// Binary search with sliding window solution
class Solution {
public:
    int smallestDistancePair(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        int left = 0, right = nums.back() - nums.front() + 1;
        while (left < right) {
            const auto mid = left + (right - left) / 2;
            if (possible(mid, nums, k)) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    bool possible(const int guess, const vector<int>& nums, const int k) {
        int count = 0, left = 0;
        for (int right = 0; right < nums.size(); ++right) {
            while ((nums[right] - nums[left]) > guess) {
                ++left;
            }
            count += right - left;
        }
        return count >= k;
    }
};

kamyu-c-find-kth-bit-in-nth-binary-strin:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    char findKthBit(int n, int k) {
        int flip = 0;  // init bit (S1) is 0
        for (int l = (1 << n) - 1; k > 1; l /= 2) {  // loop from Sn to S1, early return if k == 1
            if (k == l / 2 + 1) {
                flip ^= 1;  // hit mid, xor 1
                break;
            }
            if (k > l / 2) {
                k = l + 1 - k;
                flip ^= 1;  // right-hand side, invert once
            }
        }
        return '0' + flip;
    }
};

