            int curr = 0;
            for (int c = 0; c < size(matrix[0]); ++c) {
                curr = curr ^ matrix[r][c];
                if (r == 0) {
                    matrix[r][c] = curr;
                } else {
                    matrix[r][c] = curr ^ matrix[r - 1][c];
                }
                vals.emplace_back(matrix[r][c]);
            }
        }
        nth_element(begin(vals), begin(vals) + k - 1, end(vals), greater<int>());
        return vals[k - 1];
    }
};

kamyu-c-find-largest-value-in-each-tree-:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */

class Solution {
public:
    vector<int> largestValues(TreeNode* root) {
        vector<int> result;
        largestValuesHelper(root, 0, &result);
        return result;
    }
private:
    void largestValuesHelper(TreeNode* root, int depth, vector<int> *result) {
        if (!root) {
            return;
        }
        if (depth == result->size()) {
            result->emplace_back(root->val);
        } else {
            (*result)[depth] = max((*result)[depth], root->val);
        }
        largestValuesHelper(root->left, depth + 1, result);
        largestValuesHelper(root->right, depth + 1, result);
    }
 };

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    vector<int> largestValues(TreeNode* root) {
        if (!root) {
            return {};
        }
        vector<int> result;
        vector<TreeNode*> curr, next;
        curr.emplace_back(root);
        while (!curr.empty()) {
            int max_val = numeric_limits<int>::min();
            next.clear();
            for (const auto& node : curr) {
                max_val = max(max_val, node->val);
                if (node->left) {
                    next.emplace_back(node->left);
                }
                if (node->right) {
                    next.emplace_back(node->right);
                }
            }
            result.emplace_back(max_val);
            swap(curr, next);
        }
        return result;
    }
};

