                        result = max(result, *ret + (*ret2 + 1));
                        *ret = max(*ret, *ret2 + 1);
                    }
                }
                return result;
            };

            return iter_dfs();
        };

        const int d1 = tree_diameter(edges1);
        const int d2 = tree_diameter(edges2);
